def word_shingles(text: str, k: int = SHINGLE_SIZE) -> set[str]:
    words = text.split()
    if len(words) < k:
        return {" ".join(words)} if words else set()
    return {" ".join(words[i : i + k]) for i in range(len(words) - k + 1)}

def redact(text: str, ner_names: list[str], use_gazetteer: bool = True) -> tuple[str, dict]:
    counts = Counter()
    examples = {}
    ner_only_names: list[str] = []
    ner_overlap_names: list[str] = []

    def _sub(pattern: re.Pattern, tag: str, s: str) -> str:
        def repl(m: re.Match) -> str:
            counts[tag] += 1
            if tag not in examples:
                examples[tag] = m.group(0)
            return f"[{tag}]"

        return pattern.sub(repl, s)

    text = _sub(EMAIL_RE, "EMAIL", text)
    text = _sub(PHONE_RE, "PHONE", text)
    text = _sub(IPV4_RE, "IP", text)

    # Real NER pass, first - so the gazetteer pass below only reports names
    # the model itself did NOT already catch (a clean "gazetteer recall
    # beyond the model" signal, rather than double-counting the same hit).
    for name in ner_names:
        occurrences = text.count(name)
        if occurrences == 0:
            continue
        counts["NAME_NER"] += occurrences
        examples.setdefault("NAME_NER", name)
        if name in ALL_NAMES:
            ner_overlap_names.append(name)
        else:
            ner_only_names.append(name)
        text = text.replace(name, "[NAME_NER]")

    def name_repl(m: re.Match) -> str:
        tok = m.group(0)
        if tok in AMBIGUOUS_NAMES:
            counts["NAME_AMBIGUOUS"] += 1
            examples.setdefault("NAME_AMBIGUOUS", f"{tok} ({AMBIGUOUS_NAMES[tok]})")
        else:
            counts["NAME_HIGH_CONFIDENCE"] += 1
            examples.setdefault("NAME_HIGH_CONFIDENCE", tok)
        return "[NAME]"

    if use_gazetteer:
        text = NAME_TOKEN_RE.sub(name_repl, text)
    return text, {
        "counts": dict(counts),
        "examples": examples,
        "ner_only_names": ner_only_names,
        "ner_overlap_names": ner_overlap_names,
    }

def license_status(license_value: str | None) -> tuple[str, str]:
    """Returns (status, reason). This is the provenance gate."""
    if not license_value:
        return "BLOCKED", "No license declared by the publisher - unknown provenance cannot ship."
    if license_value in COPYLEFT_LICENSES:
        return (
            "BLOCKED",
            f"{license_value} is copyleft; training on it without a deliberate legal decision "
            "would put the whole corpus's licensing in question.",
        )
    if license_value.lower() in {l.lower() for l in ALLOWED_LICENSES}:
        return "CLEAN", f"{license_value} permits training use with attribution."
    return "BLOCKED", f"{license_value} is not on the allow-list and has not been reviewed."

def cleaning_script_hash() -> dict:
    """Hash every stage script that actually ran, so a later re-run can prove
    the code producing this manifest hasn't changed - the same check widget 9
    demonstrates. Sorted glob -> deterministic across OS/filesystem ordering."""
    stage_files = sorted(
        glob.glob(os.path.join(PIPELINE_DIR, "stage*.py"))
        + [os.path.join(PIPELINE_DIR, "common.py"), os.path.join(PIPELINE_DIR, "corpora.py")]
    )
    per_file = {os.path.basename(p): sha256_file(p) for p in stage_files}
    combined = hashlib.sha256("".join(per_file[k] for k in sorted(per_file)).encode("utf-8")).hexdigest()
    return {"per_file_sha256": per_file, "combined_script_hash_sha256": combined}

class Block(nn.Module):
    def __init__(self, d, h):
        super().__init__()
        self.ln1, self.ln2 = nn.LayerNorm(d), nn.LayerNorm(d)
        self.attn = nn.MultiheadAttention(d, h, batch_first=True)
        self.mlp = nn.Sequential(nn.Linear(d, 4 * d), nn.GELU(), nn.Linear(4 * d, d))

    def forward(self, x, mask):
        h = self.ln1(x)
        a, _ = self.attn(h, h, h, attn_mask=mask, need_weights=False)
        x = x + a
        return x + self.mlp(self.ln2(x))

def phase_at(frac):
    acc = 0.0
    for i, (pid, wgt) in enumerate(PHASES):
        nxt = acc + wgt
        if frac < nxt or i == len(PHASES) - 1:
            return i, acc, nxt
        acc = nxt
    return len(PHASES) - 1, acc, 1.0

def lr_at(frac, peak, warmup=0.02, anneal_start=0.90, floor_frac=0.10):
    if frac < warmup:
        return peak * frac / warmup
    if frac < anneal_start:
        t = (frac - warmup) / (anneal_start - warmup)
        return peak * (floor_frac + (1 - floor_frac) * 0.5 * (1 + math.cos(math.pi * t)))
    return peak * floor_frac * (1 - (frac - anneal_start) / (1 - anneal_start))


